package com.brannenservices.fieldassistant

import android.app.Activity
import android.graphics.*
import android.os.Bundle
import android.view.*
import kotlin.math.*

class MainActivity:Activity(){
 override fun onCreate(b:Bundle?){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);window.setFlags(1024,1024);window.decorView.systemUiVisibility=5894;setContentView(GameView(this))}
 class GameView(a:Activity):View(a){
  data class Bird(var x:Float,var hp:Int,val max:Int,val boss:Boolean=false,var hit:Int=-1,var flash:Float=0f)
  data class Beer(val x:Float,var taken:Boolean=false)
  val W=640;val H=360;val G=278f;val WORLD=3000f;val frame=Bitmap.createBitmap(W,H,Bitmap.Config.ARGB_8888);val c=Canvas(frame)
  val p=Paint().apply{isAntiAlias=false};val pix=Paint().apply{isAntiAlias=false;isFilterBitmap=false};var px=105f;var py=G;var vy=0f;var cam=0f;var face=1;var joy=0f;var joyId=-1
  var started=false;var dead=false;var won=false;var hp=100;var score=0;var cans=0;var attack=0f;var attackId=0;var hurt=0f;var t=0f;var last=System.nanoTime();var combo=0;var comboT=0f;var wave=1;var msg="";var msgT=0f
  val birds=mutableListOf(Bird(470f,2,2),Bird(760f,2,2),Bird(1080f,3,3),Bird(1450f,3,3),Bird(1880f,4,4),Bird(2470f,12,12,true));val beers=mutableListOf(Beer(650f),Beer(1330f),Beer(2050f));val obstacles=floatArrayOf(900f,1510f,2300f)
  override fun onDraw(o:Canvas){val n=System.nanoTime();val dt=((n-last)/1e9f).coerceAtMost(.04f);last=n;if(started&&!dead&&!won)update(dt);drawGame();o.drawBitmap(frame,null,Rect(0,0,width,height),pix);postInvalidateOnAnimation()}
  fun update(dt:Float){t+=dt;attack=max(0f,attack-dt);hurt=max(0f,hurt-dt);comboT=max(0f,comboT-dt);msgT=max(0f,msgT-dt);if(comboT<=0)combo=0;if(abs(joy)>.12f){face=if(joy>0)1 else -1;px=(px+joy*220f*dt).coerceIn(30f,WORLD-40)};vy+=780f*dt;py+=vy*dt;if(py>G){py=G;vy=0f};cam+=(px-235f-cam)*min(1f,dt*7);cam=cam.coerceIn(0f,WORLD-W);wave=if(px<1000)1 else if(px<2000)2 else 3
   birds.forEach{b->b.flash=max(0f,b.flash-dt);if(b.hp<=0)return@forEach;val dx=px-b.x;if(abs(dx)<(if(b.boss)390f else 260f))b.x+=(if(dx>0)1 else -1)*(if(b.boss)78f else 55f)*dt;if(attack>0&&b.hit!=attackId){val d=(b.x-px)*face;if(d in 5f..105f&&py>G-90){b.hp--;b.hit=attackId;b.flash=.1f;b.x+=face*(if(b.boss)20f else 38f);combo++;comboT=1.3f;score+=(if(b.boss)250 else 100)*(1+(combo-1)/3);say(if(combo>2)"$combo HIT COMBO!" else "BONK!");if(b.hp<=0)score+=if(b.boss)1800 else 300}};if(abs(b.x-px)<(if(b.boss)48f else 31f)&&py>G-55&&hurt<=0){hp=max(0,hp-(if(b.boss)18 else 10));hurt=.7f;px+=if(dx>0)-55 else 55;if(hp<=0)dead=true}}
   beers.forEach{if(!it.taken&&abs(it.x-px)<34&&py>G-70){it.taken=true;cans++;hp=min(100,hp+25);score+=200;say("COLD ONE ACQUIRED!")}};if(birds.last().hp<=0&&px>2780)won=true}
  fun say(s:String){msg=s;msgT=1.1f};fun col(v:Int){p.color=v;p.style=Paint.Style.FILL;p.shader=null};fun r(l:Float,t:Float,rr:Float,b:Float,v:Int){col(v);c.drawRect(l,t,rr,b,p)}
  fun text(s:String,x:Float,y:Float,z:Float,v:Int,center:Boolean=false){col(v);p.typeface=Typeface.create(Typeface.MONOSPACE,Typeface.BOLD);p.textSize=z;p.textAlign=if(center)Paint.Align.CENTER else Paint.Align.LEFT;c.drawText(s,x,y,p);p.textAlign=Paint.Align.LEFT}
  fun drawGame(){sky();background();dock();props();beers.filter{!it.taken}.forEach{beer(it)};birds.filter{it.hp>0}.forEach{bird(it)};man();hud();controls();if(!started)panel("POOL NOODLE PANIC","TAP TO START");if(dead)panel("WELL, THAT WENT BAD","TAP TO TRY AGAIN");if(won)panel("LEVEL COMPLETE","ALPHA FLAMINGO DEFEATED");if(msgT>0){r(205f,304f,435f,327f,Color.rgb(14,13,29));text(msg,320f,320f,10f,Color.YELLOW,true)}}
  fun sky(){p.shader=LinearGradient(0f,38f,0f,224f,Color.rgb(52,35,111),Color.rgb(255,99,72),Shader.TileMode.CLAMP);c.drawRect(0f,0f,640f,224f,p);p.shader=null;col(Color.rgb(255,187,55));c.drawCircle(465f,145f,43f,p);for(i in 0..4)r(425f+i*9,145f+i*5,510f-i*8,148f+i*5,Color.rgb(255,215,78))}
  fun palm(x:Float){r(x,126f,x+5,224f,Color.rgb(28,38,51));for(i in -2..2){val q=Path();q.moveTo(x+2,127f);q.lineTo(x+2+i*29,113f+abs(i)*7);q.lineTo(x+7+i*12,133f);q.close();col(Color.rgb(15,62,57));c.drawPath(q,p)}}
  fun background(){r(0f,190f,640f,224f,Color.rgb(18,91,126));for(i in -1..4)palm(i*180f-(cam*.08f%180f)+78);val hx=45f-(cam*.2f%1050);r(hx,139f,hx+150,220f,Color.rgb(54,77,86));val q=Path();q.moveTo(hx-10,151f);q.lineTo(hx+72,113f);q.lineTo(hx+160,151f);q.close();col(Color.rgb(29,29,43));c.drawPath(q,p);for(i in 0..3){r(hx+18+i*32,168f,hx+35+i*32,192f,Color.rgb(255,197,74));r(hx+21+i*32,171f,hx+32+i*32,189f,Color.rgb(255,231,138))}}
  fun dock(){r(0f,224f,640f,279f,Color.rgb(78,52,39));for(i in 0..10){val x=i*66f-(cam*.65f%66);r(x,224f,x+58,272f,if(i%2==0)Color.rgb(139,88,52) else Color.rgb(119,72,47));r(x,229f,x+58,233f,Color.rgb(181,117,63));r(x+7,270f,x+15,315f,Color.rgb(57,42,36))};r(0f,279f,640f,360f,Color.rgb(12,74,96));for(i in 0..8){val x=i*91f-(cam*.4f%91);r(x,300f,x+53,303f,Color.rgb(37,134,148));r(x+30,330f,x+76,333f,Color.rgb(20,103,128))}}
  fun props(){sign(360f,"GOOD BEER","BAD IDEAS");sign(1660f,"NO WAKE","JUST CHAOS");sign(2750f,"BEWARE","GATORS");obstacles.forEach{wx->val x=wx-cam;if(x in -50f..690f)c.drawBitmap(SpriteArt.cooler,null,RectF(x-28,G-28,x+28,G+13),pix)};val gx=2210f-cam;if(gx in -100f..700f){col(Color.rgb(22,86,48));c.drawOval(gx-50,292f,gx+55,322f,p);r(gx+26,286f,gx+82,305f,Color.rgb(22,86,48));r(gx+55,289f,gx+59,293f,Color.YELLOW)};val ex=2860f-cam;if(ex in -80f..720f){c.drawBitmap(SpriteArt.exit,null,RectF(ex-40,G-100,ex+40,G),pix);text("EXIT",ex,G-104,10f,Color.YELLOW,true)}}
  fun sign(wx:Float,a:String,b:String){val x=wx-cam;if(x !in -100f..740f)return;r(x-3,184f,x+3,225f,Color.rgb(62,38,27));r(x-48,164f,x+48,184f,Color.rgb(188,135,73));text(a,x,174f,8f,Color.rgb(37,27,26),true);text(b,x,182f,8f,Color.rgb(37,27,26),true)}
  fun man(){if(hurt>0&&(hurt*12).toInt()%2==0)return;val x=px-cam;val bob=if(abs(joy)>.12f&&py>=G)sin(t*13)*2 else 0.0;val dst=RectF(x-36,py-108+bob.toFloat(),x+36,py+bob.toFloat());if(face>0)c.drawBitmap(SpriteArt.man,null,dst,pix)else{c.save();c.scale(-1f,1f,x,py);c.drawBitmap(SpriteArt.man,null,RectF(x-36,py-108+bob.toFloat(),x+36,py+bob.toFloat()),pix);c.restore()};val sx=x+face*22;val sy=py-57;col(Color.rgb(35,166,255));p.strokeWidth=10f;if(attack>0){val a=(1-attack/.2f).coerceIn(0f,1f);val deg=if(face>0)-55+a*100 else 235-a*100;val z=Math.toRadians(deg.toDouble());c.drawLine(sx,sy,sx+cos(z).toFloat()*88,sy+sin(z).toFloat()*88,p)}else c.drawLine(sx,sy,x+face*62,py-75,p)}
  fun bird(b:Bird){val x=b.x-cam;if(x !in -110f..750f)return;val s=if(b.boss)1.6f else 1f;val w=72*s;val h=96*s;val dst=RectF(x-w/2,G-h,x+w/2,G);if(b.flash>0){p.colorFilter=PorterDuffColorFilter(Color.WHITE,PorterDuff.Mode.SRC_ATOP);c.drawBitmap(SpriteArt.flamingo,null,dst,p);p.colorFilter=null}else c.drawBitmap(SpriteArt.flamingo,null,dst,pix);if(b.boss){text("ALPHA",x,G-h-7,8f,Color.YELLOW,true);r(x-35,G-h-3,x+35,G-h+2,Color.rgb(55,25,30));r(x-35,G-h-3,x-35+70f*b.hp/b.max,G-h+2,Color.RED)}}
  fun beer(q:Beer){val x=q.x-cam;if(x !in -30f..670f)return;val y=G-38+sin(t*5+q.x)*3;c.drawBitmap(SpriteArt.beer,null,RectF(x-13,y-24,x+13,y+20),pix)}
  fun hud(){r(0f,0f,640f,38f,Color.rgb(12,11,29));text("HOLD MY BEER",12f,14f,10f,Color.YELLOW);r(12f,21f,184f,31f,Color.rgb(55,45,54));r(15f,24f,15f+166f*hp/100f,28f,if(hp>30)Color.rgb(42,215,70) else Color.RED);text("FLORIDA MAN",320f,17f,18f,Color.YELLOW,true);text("POOL NOODLE PANIC  •  WAVE $wave/3",320f,30f,7f,Color.WHITE,true);text("SCORE $score",520f,14f,8f,Color.WHITE);text("COLD ONES x $cans",520f,28f,8f,Color.WHITE);if(combo>1)text("COMBO x$combo",455f,48f,9f,Color.YELLOW)}
  fun controls(){col(Color.argb(175,10,20,35));c.drawCircle(48f,321f,31f,p);col(Color.rgb(25,80,158));c.drawCircle(555f,321f,25f,p);col(Color.rgb(190,30,38));c.drawCircle(610f,321f,25f,p);text("JUMP",555f,325f,8f,Color.WHITE,true);text("WHACK",610f,325f,8f,Color.WHITE,true)}
  fun panel(a:String,b:String){r(102f,126f,538f,220f,Color.argb(235,11,11,26));r(107f,131f,533f,215f,Color.rgb(36,27,60));text(a,320f,165f,20f,Color.YELLOW,true);text(b,320f,193f,10f,Color.WHITE,true)}
  fun reset(){px=105f;py=G;vy=0f;cam=0f;hp=100;score=0;cans=0;dead=false;won=false;combo=0;birds.clear();birds.addAll(listOf(Bird(470f,2,2),Bird(760f,2,2),Bird(1080f,3,3),Bird(1450f,3,3),Bird(1880f,4,4),Bird(2470f,12,12,true)));beers.clear();beers.addAll(listOf(Beer(650f),Beer(1330f),Beer(2050f)))}
  override fun onTouchEvent(e:MotionEvent):Boolean{when(e.actionMasked){MotionEvent.ACTION_DOWN,MotionEvent.ACTION_POINTER_DOWN->{val i=e.actionIndex;val id=e.getPointerId(i);val x=e.getX(i)/width*W;val y=e.getY(i)/height*H;if(!started||dead||won){if(dead||won)reset();started=true;return true};if(x<130&&y>270){joyId=id;joy=((x-48)/48).coerceIn(-1f,1f)}else if(x>585&&y>285){attack=.2f;attackId++}else if(x>525&&y>285&&py>=G-1){vy=-330f}};MotionEvent.ACTION_MOVE->{if(joyId>=0)for(i in 0 until e.pointerCount)if(e.getPointerId(i)==joyId){val x=e.getX(i)/width*W;joy=((x-48)/48).coerceIn(-1f,1f)}};MotionEvent.ACTION_UP,MotionEvent.ACTION_POINTER_UP,MotionEvent.ACTION_CANCEL->{if(e.getPointerId(e.actionIndex)==joyId){joyId=-1;joy=0f}}};return true}
 }
}